{"function":"() => {
// list focusable sequence via DOM incl shadow
const res=[];
const walk=(root)=>{root.querySelectorAll('*').forEach(e=>{ if(e.matches('a[href],button:not([disabled]),input,select,textarea,[tabindex]')&&e.tabIndex>=0){const r=e.getBoundingClientRect();res.push((e.getRootNode().host?e.getRootNode().host.tagName+'>>':'')+e.tagName+'|'+(e.getAttribute('aria-label')||e.textContent.trim().slice(0,25))+'|'+Math.round(r.x)+','+Math.round(r.y)+','+Math.round(r.width)+'x'+Math.round(r.height));} if(e.shadowRoot) walk(e.shadowRoot);});};
walk(document);
return res.slice(0,40);}"}

